            Claim claim = claims.saveAndFlush(made.get(i));
            audit.record(ClaimAudit.line("CLAIM_ADDED", claim, persons.get(i).getName(), by));
            ClaimRules.log(claim, sheet, log, people, rates, grades, by);
        }
